{
  "results": [
    {
      "server": "council",
      "tools": [
        {
          "tool_name": "council__council_status",
          "description": "Where the council stands for your seat: the agenda item, any pending motion, what happened since you last looked, and — if a round is open for you — exactly what you may submit, with reasons. Never blocks.",
          "score": 2.127629280090332,
          "input_schema": {
            "type": "object",
            "properties": {
              "since": {
                "type": "integer",
                "description": "show events after this seq (default: since your last look)"
              }
            },
            "additionalProperties": false
          }
        },
        {
          "tool_name": "council__council_wait",
          "description": "Block until a round is open that you have not yet answered, or the meeting adjourns, then return the same view as council_status. Returns early (saying so) after max_wait_s; just call it again. This is how you wait your turn: nobody is penalized for answering slowly.",
          "score": 2.037853479385376,
          "input_schema": {
            "type": "object",
            "properties": {
              "max_wait_s": {
                "type": "number"
              }
            },
            "additionalProperties": false
          }
        },
        {
          "tool_name": "council__council_record",
          "description": "The council's full record so far (minutes): every round, every revealed intent, every outcome. For catching up after arriving late or restarting.",
          "score": 1.9631723165512085,
          "input_schema": {
            "type": "object",
            "properties": {},
            "additionalProperties": false
          }
        },
        {
          "tool_name": "council__council_submit",
          "description": "Submit your sealed intent for the open round. Nobody sees it until the round closes, when everyone's are revealed together. Your submission is final for the round: think before you submit. `action` must be one of those listed for you in the view.",
          "score": 1.1882729530334473,
          "input_schema": {
            "type": "object",
            "properties": {
              "round": {
                "type": "string"
              },
              "action": {
                "type": "string"
              },
              "text": {
                "type": "string"
              },
              "vote": {
                "type": "string",
                "enum": [
                  "yes",
                  "no",
                  "abstain"
                ]
              }
            },
            "required": [
              "round",
              "action"
            ],
            "additionalProperties": false
          }
        }
      ]
    }
  ],
  "total_hidden_tools": 4,
  "status": "ready",
  "note": null
}

